import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CSVParser_iterator_TriageGen2Test {

    @Test
    public void testIteratorNormalFlow() throws IOException {
        String csv = "a,b\n1,2\n3,4";
        try (CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();

            assertTrue(iterator.hasNext());
            CSVRecord record1 = iterator.next();
            assertEquals("a", record1.get(0));
            assertEquals("b", record1.get(1));

            assertTrue(iterator.hasNext());
            CSVRecord record2 = iterator.next();
            assertEquals("1", record2.get(0));
            assertEquals("2", record2.get(1));

            assertTrue(iterator.hasNext());
            CSVRecord record3 = iterator.next();
            assertEquals("3", record3.get(0));
            assertEquals("4", record3.get(1));

            assertFalse(iterator.hasNext());
            assertFalse(iterator.hasNext()); // Double check hasNext
        }
    }














}

